export fn line_sweep(v:[*]const i64,n:usize)callconv(.c)f64{if(n<1 or n>17)return -1e300;const count=v[0];if(count<0 or count>8 or n!=@as(usize,@intCast(1+2*count)))return -1e300;if(count==0)return 0;var line=[_]i32{0}**22;for(0..@intCast(count))|i|{const s=v[1+2*i];const e=v[2+2*i];if(s<0 or e<s or e>20)return -1e300;line[@intCast(s)]+=1;line[@intCast(e+1)]-=1;}var c:i32=0;var m:i32=0;for(line)|d|{c+=d;if(c>m)m=c;}return if(m>1) 1.0 else 0.0;}
